<?php

gc_disable();

final class Tree
{
    public $left = null;
    public $right = null;

    public function __construct(int $depth)
    {
        if ($depth > 0) {
            $nextDepth = $depth - 1;
            $this->left = new self($nextDepth);
            $this->right = new self($nextDepth);
        }
    }

    public function check(): int
    {
        if ($this->left === null) {
            return 1;
        }

        return 1 + $this->left->check() + $this->right->check();
    }
}

