<?php

const MODULUS = 139968;
const MULTIPLIER = 3877;
const INCREMENT = 29573;
const LINE_WIDTH = 60;

function writeAll(string $data): void
{
    $length = strlen($data);
    $offset = 0;

    while ($offset < $length) {
        $written = fwrite(STDOUT, substr($data, $offset));
        if ($written === false || $written === 0) {
            exit(1);
        }
        $offset += $written;
    }
}

function gcdInt(int $a, int $b): int
{
    while ($b !== 0) {
        $remainder = $a % $b;
        $a = $b;
        $b = $remainder;
    }
    return $a;
}

function buildLookup(string $symbols, array $probabilities): string
{
    $cumulative = [];
    $sum = 0.0;

    foreach ($probabilities as $probability) {
        $sum += $probability;
        $cumulative[] = $sum;
    }

    $lookup = '';
    $symbolIndex = 0;
    $lastIndex = strlen($symbols) - 1;
    $count = count($cumulative);

    for ($seed = 0; $seed < MODULUS; ++$seed) {
        $r = $seed / MODULUS;

        while (
            $symbolIndex + 1 < $count &&
            !($cumulative[$symbolIndex] > $r)
        ) {
            ++$symbolIndex;
        }

        if ($symbolIndex > $lastIndex) {
            $symbolIndex = $lastIndex;
        }

        $lookup .= $symbols[$symbolIndex];
    }

    return $lookup;
}

function buildRandomPeriod(int $startingSeed, string $lookup): string
{
    $seed = $startingSeed;
    $period = '';

    do {
        $seed = ($seed * MULTIPLIER + INCREMENT) % MODULUS;
        $period .= $lookup[$seed];
    } while ($seed !== $startingSeed);

    return $period;
}

function advanceSeed(int $seed, int $steps): int
{
    for ($i = 0; $i < $steps; ++$i) {
        $seed = ($seed * MULTIPLIER + INCREMENT) % MODULUS;
    }
    return $seed;
}

function writePeriodicSequence(string $period, int $length): void
{
    if ($length <= 0) {
        return;
    }

    $periodLength = strlen($period);
    $baseBlockLength = intdiv(
        $periodLength * LINE_WIDTH,
        gcdInt($periodLength, LINE_WIDTH)
    );

    $targetBlockLength = 700000;
    $factor = max(1, intdiv(
        $targetBlockLength + $baseBlockLength - 1,
        $baseBlockLength
    ));
    $blockLength = $baseBlockLength * $factor;

    $rawBlock = str_repeat($period, intdiv($blockLength, $periodLength));
    $formattedBlock = chunk_split($rawBlock, LINE_WIDTH, "\n");
    unset($rawBlock);

    $fullBlocks = intdiv($length, $blockLength);
    for ($i = 0; $i < $fullBlocks; ++$i) {
        writeAll($formattedBlock);
    }

    $remaining = $length % $blockLength;
    if ($remaining > 0) {
        $wholePeriods = intdiv($remaining, $periodLength);
        $partialLength = $remaining % $periodLength;

        $tail = str_repeat($period, $wholePeriods);
        if ($partialLength > 0) {
            $tail .= substr($period, 0, $partialLength);
        }

        writeAll(chunk_split($tail, LINE_WIDTH, "\n"));
    }
}

