function multiplyMatrix(array $vector, int $n, bool $transpose): array
{
    $result = [];
    $unrolledLimit = $n - 3;

    for ($i = 0; $i < $n; ++$i) {
        $sum = 0.0;

        if ($transpose) {
            $denominator = intdiv($i * ($i + 1), 2) + 1;
            $increment = $i + 2;
        } else {
            $denominator = intdiv(($i + 1) * ($i + 2), 2);
            $increment = $i + 1;
        }

        $j = 0;

        for (; $j < $unrolledLimit; $j += 4) {
            $sum += $vector[$j] / $denominator;
            $denominator += $increment++;

            $sum += $vector[$j + 1] / $denominator;
            $denominator += $increment++;

            $sum += $vector[$j + 2] / $denominator;
            $denominator += $increment++;

            $sum += $vector[$j + 3] / $denominator;
            $denominator += $increment++;
        }

        for (; $j < $n; ++$j) {
            $sum += $vector[$j] / $denominator;
            $denominator += $increment++;
        }

        $result[$i] = $sum;
    }

    return $result;
}

function multiplyAtA(array $vector, int $n): array
{
    $temporary = multiplyMatrix($vector, $n, false);
    return multiplyMatrix($temporary, $n, true);
}

